   await edit('costs',fixture.vehicle,'vehicle_costs',fixture.cost,'cost.link_expense');const linked=await save('cost.link_expense',{}, {expense_category_id:{id:fixture.category.id,query:label('Vehicle category')}});must(linked.proposed.effects.length>0,'Expense link effects are shown before acceptance');
   await edit('costs',fixture.vehicle,'vehicle_costs',fixture.cost,'cost.correct');const corrected=await save('cost.correct',{occurred_on:day3,kind:'insurance',title:label('Insurance corrected'),total_minor:'101.00',currency_code:'EUR',link_expense:true,correct_expense:true,notes:'Explicit reversal and replacement'},{expense_category_id:fixture.category.id});fixture.correctedCost=corrected.result.record_id;must(corrected.proposed.effects.length>=2,'Linked correction explains reversal and replacement effects');same((await record('vehicle_costs',fixture.cost)).total_minor,'10000','Original cost remains immutable evidence');
