  async function localOCR(kind,format){
   const number=(kind==='receipt'?0:3)+['png','jpeg','pdf'].indexOf(format),reading=String(1520+number*10),forbidden='987654';
   const lines=kind==='receipt'?['SYNTHETIC RECEIPT',today,'Diesel 2.000 l','Preis 1.500 EUR/l','Gesamt 3.00 EUR','Odometer '+reading+' km']:['SYNTHETIC ODOMETER',reading+' km'];
   const mime=format==='pdf'?'application/pdf':'image/'+format;let bytes;
   if(format==='pdf'){
    const pdfContext=await browser.newContext({serviceWorkers:'block'});
    await pdfContext.route('**/*',route=>route.abort());
    try{const pdfPage=await pdfContext.newPage(),escape=s=>s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
     await pdfPage.setContent('<!doctype html><html><head><meta charset="utf-8"><style>@page{size:A4;margin:12mm}body{margin:0;background:white;color:black;font:40px/1.8 monospace}.sheet{height:250mm;box-sizing:border-box;padding:5mm;break-after:page}.sheet:last-child{break-after:auto}p{margin:0}</style></head><body><section class="sheet">'+lines.map(line=>'<p>'+escape(line)+'</p>').join('')+'</section><section class="sheet"><p>SYNTHETIC SECOND PAGE</p><p>Odometer '+forbidden+' km</p><p>This page must never supply a proposal.</p></section></body></html>');
     bytes=await pdfPage.pdf({format:'A4',preferCSSPageSize:true,printBackground:true});
     same((bytes.toString('latin1').match(/\/Type\s*\/Page\b/g)||[]).length,2,'Literal source PDF actually contains two pages');
    }finally{await pdfContext.close();}
   }else{
    const encoded=await page.evaluate(({lines,mime})=>{const canvas=document.createElement('canvas');canvas.width=1400;canvas.height=900;const c=canvas.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,1400,900);c.fillStyle='#111';c.font='bold 64px monospace';lines.forEach((line,i)=>c.fillText(line,60,100+i*115));return canvas.toDataURL(mime,0.98).split(',')[1];},{lines,mime});bytes=Buffer.from(encoded,'base64');
   }
   const sourceName='synthetic-'+kind+'-'+format+'-'+suffix+'.'+(format==='jpeg'?'jpg':format),inputHash=crypto.createHash('sha256').update(bytes).digest('hex');
   await fs.writeFile(path.join(output,'ocr-'+kind+'-'+format+'.input.'+(format==='jpeg'?'jpg':format)),bytes);
   await go('capture',fixture.vehicle);const current=await workspace('capture',fixture.vehicle);must(current.options.capture_available===true,'Actual local OCR is configured for '+kind+'/'+format);report.capabilities.localOCR=true;
   await page.locator('#fm-upload [name=file]').setInputFiles({name:sourceName,mimeType:mime,buffer:bytes});await page.locator('#fm-upload-submit').click();await page.getByText(/Datei am Fahrzeug gespeichert/, {exact:false}).waitFor();await page.locator('#fm-attachments-refresh').click();await page.waitForFunction(()=>!document.querySelector('#fm-attachments-refresh').disabled);
   const attachments=await json('/api/v1/m/fuel/vehicles/'+fixture.vehicle+'/attachments'),attachment=attachments.find(a=>a.name===sourceName);must(Boolean(attachment)&&attachment.media_type===mime,'Original '+format+' source was actually uploaded and authorized');
   const download=await context.request.get(base+'/attachments/'+attachment.id,{maxRedirects:0});must(download.status()===200,'Protected original bytes remain currently authorized');const canonical=await download.body();same(canonical.length,attachment.size,'Canonical original byte count matches actual metadata');const sourceHash=crypto.createHash('sha256').update(canonical).digest('hex');
   if(format==='pdf')same(sourceHash,inputHash,'Uploaded PDF original retains its exact two-page bytes');
   await fs.writeFile(path.join(output,'ocr-'+kind+'-'+format+'.canonical.'+(format==='jpeg'?'jpg':format)),canonical);
   await save('capture.stage',{attachment_id:attachment.id,kind},{odometer_series_id:fixture.series});
   let job;for(let attempt=0;attempt<45;attempt++){const rows=(await workspace('capture',fixture.vehicle)).records;job=rows.find(r=>r.attachment_id===attachment.id&&r.kind===kind);if(job?.state==='review'||job?.state==='failed')break;await sleep(1000);}must(job?.state==='review','Actual extractor reaches review for '+kind+'/'+format);
   await go('capture',fixture.vehicle);const jobRow=page.locator('#fm-records tr').filter({hasText:kind}).filter({has:page.locator('[data-row-action="capture.confirm"]')}).first();await jobRow.locator('[data-row-action="capture.confirm"]').click();const form=await open('capture.confirm');await form.locator('[data-capture-source]').waitFor();must((await form.innerText()).includes('Original')&&await form.locator('a[href="/attachments/'+attachment.id+'"]').count()===1,'OCR review uses the exact protected '+format+' attachment');
   const actual=await workspace('capture',fixture.vehicle,{job:job.id}),proposal=actual.records.find(r=>r.id===job.id)?.proposal;must(proposal?.source==='local_ocr'&&/^[a-f0-9]{64}$/.test(proposal.text_sha256),'Proposal is produced by the actual local worker');
   const candidates=Object.values(proposal.candidates||{}).flat();must(candidates.length>0&&candidates.every(candidate=>candidate.attachment_id===attachment.id),'Every actual candidate binds the correct original attachment');must((proposal.candidates.odometer||[]).some(candidate=>candidate.value===reading),'Actual '+format+' extractor recognizes the printed first-source odometer');
   if(format==='pdf'){const visible=(await form.locator('[data-capture-source]').innerText())+' '+await page.locator('#fuel-module').innerText();must(/erste[nr]?\s+(?:PDF[- ]?)?Seite|PDF[- ]?Seite\s*1|nur\s+Seite\s*1/i.test(visible),'PDF review explicitly explains first-page-only proposals');must(!candidates.some(candidate=>String(candidate.value).includes(forbidden)||candidate.evidence.includes(forbidden))&&!Object.values(proposal.values||{}).some(value=>String(value).includes(forbidden)),'Actual PDF page2 odometer cannot leak into first-page proposals');}
   if(kind==='receipt'){await preview('capture.confirm',{occurred_on:today,odometer:reading,quantity:'2',unit_price:'1.5',total_minor:'3.00',fuel_type:'diesel',quantity_unit:'l',currency_code:'EUR',station:label('OCR '+format+' receipt manually checked'),full_tank:false,notes:'Actual '+format+' source; values explicitly reviewed'},{odometer_series_id:{id:fixture.series,query:label('Original counter')}});await execute();await nextOperation();}
   else{const before=(await workspace('history',fixture.vehicle)).records.length;const p=await preview('capture.confirm',{observed_on:today,reading,notes:'Actual '+format+' odometer original explicitly checked'});must(Boolean(p.before?.current_comparison),'Photo review compares actual previous/lower/upper sources');fixture.observation=(await execute()).record_id;await nextOperation();same((await workspace('history',fixture.vehicle)).records.length,before,'Confirmed '+format+' odometer never invents a fillup');same((await record('odometer_observations',fixture.observation)).reading,reading+'.000000','Confirmed '+format+' source becomes a separate actual observation');}
   report.ocr_sources.push({job_id:job.id,attachment_id:attachment.id,kind,format,media_type:mime,sha256:sourceHash,input_sha256:inputHash,bytes:canonical.length,first_page_reading:reading,forbidden_pdf_reading:format==='pdf'?forbidden:null});
   const evidence=JSON.stringify(report.ocr_sources);if(Buffer.byteLength(evidence)>8192)throw Error('Bounded OCR source evidence exceeded limit');await fs.writeFile(path.join(output,'ocr-source-evidence.json'),evidence);
  }
